12	// Street geometry from City::makeDowntown's documented layout: 3x3 blocks on
13	// a 64-unit pitch, 16-unit streets centered between block edges at ±32.
14	constexpr float kStreetCenter = 32.f;
15	constexpr float kStreetWidth = 16.f;
16	
17	// Ground/asphalt/sidewalk palette — warm, low-poly-friendly flats.
18	constexpr Color kGrass{116, 153, 86, 255};
19	constexpr Color kAsphalt{68, 70, 78, 255};
20	constexpr Color kPlaza{188, 178, 158, 255};
21	constexpr Color kSidewalk{158, 152, 140, 255};
22	
23	// Draws `model` scaled UNIFORMLY to stand `worldHeight` tall, feet on the
24	// ground, centered on (centerX, centerZ) — the Uniform size contract:
25	// the asset keeps its proportions regardless of any collision box.
26	void drawModelUniform(const Model& model, float centerX, float centerZ,
27	                      float worldHeight, Color tint) {
28	    const BoundingBox bb = GetModelBoundingBox(model);
29	    const float h = bb.max.y - bb.min.y;
30	    if (h <= 0.f) return;
31	    const float s = worldHeight / h;
32	    const Vector3 position{centerX - (bb.min.x + bb.max.x) * 0.5f * s,
33	                           -bb.min.y * s,
34	                           centerZ - (bb.min.z + bb.max.z) * 0.5f * s};
35	    DrawModelEx(model, position, Vector3{0.f, 1.f, 0.f}, 0.f, Vector3{s, s, s}, tint);
36	}
37	
38	// Draws `model` scaled and translated so its bounding box exactly fills the
39	// axis-aligned footprint [minX,maxX]x[minZ,maxZ] with the given height,
40	// sitting on the ground plane — the Fill size contract (buildings).
41	// Rotation-free: KayKit city pieces face +Z at identity, which matches the
42	// street-facing fronts of the downtown layout.
43	void drawModelFittedToAABB(const Model& model, float minX, float minZ, float maxX,
44	                           float maxZ, float height, Color tint) {
45	    const BoundingBox bb = GetModelBoundingBox(model);
46	    const Vector3 size{bb.max.x - bb.min.x, bb.max.y - bb.min.y, bb.max.z - bb.min.z};
47	    if (size.x <= 0.f || size.y <= 0.f || size.z <= 0.f) return;
48	    const Vector3 scale{(maxX - minX) / size.x, height / size.y, (maxZ - minZ) / size.z};
49	    const Vector3 position{minX - bb.min.x * scale.x, -bb.min.y * scale.y,
50	                           minZ - bb.min.z * scale.z};
51	    DrawModelEx(model, position, Vector3{0.f, 1.f, 0.f}, 0.f, scale, tint);
52	}
53	
54	// Draws one KayKit road tile (origin-centered 2x2 slab) filling the world
55	// footprint worldX x worldZ at (cx, cz). The Fill scaling happens in model
56	// space, so a 90-degree yaw (X-running streets) swaps which model axis
57	// covers which world axis. Thickness is pinned rather than scaled: a true
58	// 8x fill of the 0.1-thick tile would raise a 0.8-unit curb over the flat
59	// collision plane.
60	void drawRoadTile(const Model& model, float cx, float cz, float worldX,
61	                  float worldZ, bool rotate90) {
62	    const BoundingBox bb = GetModelBoundingBox(model);
63	    const Vector3 size{bb.max.x - bb.min.x, bb.max.y - bb.min.y, bb.max.z - bb.min.z};
64	    if (size.x <= 0.f || size.y <= 0.f || size.z <= 0.f) return;
65	    constexpr float kRoadThickness = 0.05f;
66	    const Vector3 scale{(rotate90 ? worldZ : worldX) / size.x,
67	                        kRoadThickness / size.y,
68	                        (rotate90 ? worldX : worldZ) / size.z};
69	    // Base floats a hair above the grass plane to avoid coplanar flicker.
70	    DrawModelEx(model, Vector3{cx, 0.01f, cz}, Vector3{0.f, 1.f, 0.f},
71	                rotate90 ? 90.f : 0.f, scale, WHITE);
72	}
73	
74	// Composite plaza fountain — the KayKit city pack has no fountain model, so
75	// it is built from primitives on the authored footprint: a stone basin wall,
76	// two smaller tiers, and translucent water discs. `worldHeight` comes from
77	// the fountain's SizeSpec (the single sizing source); radii derive from the
78	// collision AABB so visuals and collider always match.
79	void drawFountain(const Building& b, float worldHeight) {
80	    const float cx = (b.minX + b.maxX) * 0.5f;
81	    const float cz = (b.minZ + b.maxZ) * 0.5f;
82	    const float radius = std::min(b.maxX - b.minX, b.maxZ - b.minZ) * 0.5f;
83	
84	    constexpr Color kStone{172, 168, 156, 255};
85	    constexpr Color kStoneDark{136, 132, 122, 255};
86	    constexpr Color kWater{70, 140, 200, 170};
87	
88	    // Tier proportions (fraction of footprint radius / total height).
89	    const float basinH = worldHeight * 0.25f;
90	    const float midH = worldHeight * 0.50f;
91	    const float topH = worldHeight * 0.25f;
92	
93	    // DrawCylinder renders capped solids, so each "water surface" is a thin
94	    // translucent disc floated just above its stone cap — recessed water
95	    // would be hidden by the cap itself.
96	
97	    // Basin: outer wall filled to the brim with water.
98	    DrawCylinder({cx, 0.f, cz}, radius, radius, basinH, 24, kStone);
99	    DrawCylinderWires({cx, 0.f, cz}, radius, radius, basinH, 24, kStoneDark);
100	    DrawCylinder({cx, basinH, cz}, radius * 0.88f, radius * 0.88f, 0.03f, 24, kWater);
101	
102	    // Middle tier: column carrying a smaller bowl with its own water disc.
103	    DrawCylinder({cx, basinH, cz}, radius * 0.18f, radius * 0.26f, midH, 12, kStone);
104	    DrawCylinder({cx, basinH + midH * 0.7f, cz}, radius * 0.45f, radius * 0.45f,
105	                 midH * 0.3f, 20, kStone);
106	    DrawCylinder({cx, basinH + midH, cz}, radius * 0.38f, radius * 0.38f, 0.03f,
107	                 20, kWater);
108	
109	    // Top spout: a slim finial peaking at exactly worldHeight.
110	    DrawCylinder({cx, basinH + midH, cz}, radius * 0.07f, radius * 0.14f, topH,
111	                 10, kStoneDark);
112	}
