118	void RaylibRenderer::beginFrame(const CameraPose& pose) {
119	    camera_.position = {pose.position.x, pose.position.y + 1.7f, pose.position.z};
120	    const float pitchRad = degToRad(pose.pitchDeg);
121	    const float yawRad = degToRad(pose.yawDeg);
122	    const Vector3 dir{std::sin(yawRad) * std::cos(pitchRad), std::sin(pitchRad),
123	                      std::cos(yawRad) * std::cos(pitchRad)};
124	    camera_.target = {camera_.position.x + dir.x, camera_.position.y + dir.y,
125	                      camera_.position.z + dir.z};
126	    camera_.up = {0.f, 1.f, 0.f};
127	    camera_.fovy = 70.f;
128	    camera_.projection = CAMERA_PERSPECTIVE;
129	
130	    // Atmosphere: models carry the fog shader on their materials; wrapping
131	    // the whole 3D pass in BeginShaderMode routes the primitive batch
132	    // (ground plane, slabs, fountain, viewmodel) through the same shader so
133	    // everything hazes consistently. Fog distance needs the camera each
134	    // frame.
135	    if (const Shader* fog = assets_.fogShader()) {
136	        const float eye[3] = {camera_.position.x, camera_.position.y,
137	                              camera_.position.z};
138	        SetShaderValue(*fog, assets_.fogCameraLoc(), eye, SHADER_UNIFORM_VEC3);
139	        BeginMode3D(camera_);
140	        BeginShaderMode(*fog);
141	        return;
142	    }
143	    BeginMode3D(camera_);
144	}
