146	void RaylibRenderer::drawCity(const City& city) {
147	    const float half = city.halfSize();
148	
149	    // Ground: grass base with the street grid and block slabs on top.
150	    DrawPlane({0.f, 0.f, 0.f}, {half * 2.f, half * 2.f}, kGrass);
151	
152	    // Streets: KayKit road tiles when the pack is present, flat asphalt
153	    // strips otherwise. Tile pitch = street width (16), centers at multiples
154	    // of 16 so the four junctions at (+-32, +-32) land exactly on tile
155	    // centers; the arm tiles beside each junction (+-16, +-48) carry zebra
156	    // crossings where the sidewalks meet. 13 tiles cover +-104; a compressed
157	    // end-cap tile spans the last 6 units to the +-110 map edge.
158	    const Model* straight = assets_.prop("road_straight");
159	    const Model* crossing = assets_.prop("road_straight_crossing");
160	    const Model* junction = assets_.prop("road_junction");
161	    if (straight && crossing && junction) {
162	        constexpr float kTile = 16.f;
163	        for (const float sc : {-kStreetCenter, kStreetCenter}) {
164	            for (float t = -96.f; t <= 96.f; t += kTile) {
165	                if (t == -kStreetCenter || t == kStreetCenter) {
166	                    // Both streets pass through this tile; draw the 4-way
167	                    // junction art once (in the Z-running pass).
168	                    drawRoadTile(*junction, sc, t, kStreetWidth, kTile, false);
169	                    continue;
170	                }
171	                const float arm = std::fabs(std::fabs(t) - kStreetCenter);
172	                const Model& tile = (arm == kTile) ? *crossing : *straight;
173	                drawRoadTile(tile, sc, t, kStreetWidth, kTile, false);
174	                drawRoadTile(tile, t, sc, kTile, kStreetWidth, true);
175	            }
176	            for (const float e : {-107.f, 107.f}) {
177	                drawRoadTile(*straight, sc, e, kStreetWidth, 6.f, false);
178	                drawRoadTile(*straight, e, sc, 6.f, kStreetWidth, true);
179	            }
180	        }
181	    } else {
182	        for (const float c : {-kStreetCenter, kStreetCenter}) {
183	            DrawCube({c, 0.02f, 0.f}, kStreetWidth, 0.04f, half * 2.f, kAsphalt);
184	            DrawCube({0.f, 0.02f, c}, half * 2.f, 0.04f, kStreetWidth, kAsphalt);
185	        }
186	    }
187	    // Block slabs: plaza (center) is pale stone, park (north-east) stays
188	    // grass, every other block gets a sidewalk-toned slab.
189	    for (const float bx : {-64.f, 0.f, 64.f}) {
190	        for (const float bz : {-64.f, 0.f, 64.f}) {
191	            const bool plaza = bx == 0.f && bz == 0.f;
192	            const bool park = bx == 64.f && bz == 64.f;
193	            if (park) continue;
194	            DrawCube({bx, 0.04f, bz}, 48.f, 0.08f, 48.f, plaza ? kPlaza : kSidewalk);
195	        }
196	    }
197	
198	    // Street furniture (traffic lights, bushes) renders through the same
199	    // buildings pass below — City authors their positions AND colliders,
200	    // so nothing visible can be walk-through.
201	
202	    // Buildings and street props from the collision AABBs — the models scale
203	    // to fit the authoritative footprints, never the other way around.
204	    for (const Building& b : city.buildings()) {
205	        // The fountain is composed from primitives (no pack model). Must be
206	        // dispatched by id BEFORE the model lookup: modelForBuilding falls
207	        // back to a hashed generic building for uncurated ids.
208	        if (b.id == "fountain") {
209	            drawFountain(b, assets_.sizeSpecFor(b).worldHeight);
210	            continue;
211	        }
212	        if (const Model* model = assets_.modelForBuilding(b)) {
213	            const Assets::SizeSpec& spec = assets_.sizeSpecFor(b);
214	            if (spec.mode == Assets::SizeSpec::Mode::Uniform) {
215	                drawModelUniform(*model, (b.minX + b.maxX) * 0.5f,
216	                                 (b.minZ + b.maxZ) * 0.5f, spec.worldHeight, WHITE);
217	            } else {
218	                drawModelFittedToAABB(*model, b.minX, b.minZ, b.maxX, b.maxZ, b.height,
219	                                      WHITE);
220	            }
221	        } else {
222	            // Fallback primitive, tinted like the legacy renderer's boxes.
223	            const unsigned char tint =
224	                static_cast<unsigned char>(120 + (b.facadeKind * 37) % 90);
225	            const Vector3 center{(b.minX + b.maxX) * 0.5f, b.height * 0.5f,
226	                                 (b.minZ + b.maxZ) * 0.5f};
227	            DrawCube(center, b.maxX - b.minX, b.height, b.maxZ - b.minZ,
228	                     Color{tint, tint, static_cast<unsigned char>(tint + 20), 255});
229	            DrawCubeWires(center, b.maxX - b.minX, b.height, b.maxZ - b.minZ,
230	                          Color{40, 45, 60, 255});
231	        }
232	    }
233	}
