235	void RaylibRenderer::drawCharacter(const CharacterVisual& visual) {
236	    const Assets::CharacterAsset* character =
237	        assets_.characterFor(visual.variantSeed, visual.police);
238	    if (!character) {
239	        // No pack: marker cylinder, same as the pre-asset placeholder.
240	        const Vec3& p = visual.position;
241	        DrawCylinder({p.x, 0.f, p.z}, 0.35f, 0.35f, 1.8f, 12, Color{200, 120, 80, 255});
242	        DrawCylinderWires({p.x, 0.f, p.z}, 0.35f, 0.35f, 1.8f, 12, Color{60, 30, 20, 255});
243	        return;
244	    }
245	
246	    // Pick the clip: death overrides everything, gestures interrupt,
247	    // then walk/idle by movement.
248	    int clip = visual.walking ? character->walk : character->idle;
249	    if (visual.gesturePhase > 0.f && character->gesture >= 0) clip = character->gesture;
250	    if (visual.dead && character->death >= 0) clip = character->death;
251	
252	    AnimState& state = anim_[visual.variantSeed];
253	    if (state.clip != clip) {
254	        state.clip = clip;
255	        state.time = 0.f;
256	    }
257	    state.time += GetFrameTime();
258	    if (clip >= 0 && clip < character->clipCount) {
259	        // raylib bakes glTF animations at ~60 samples/second; loop by frame.
260	        const ModelAnimation& animation = character->clips[clip];
261	        const int frame =
262	            static_cast<int>(state.time * 60.f) % (animation.frameCount > 0
263	                                                       ? animation.frameCount
264	                                                       : 1);
265	        // CPU skinning on the shared model right before this entity's draw,
266	        // so several entities can reuse one model with different clocks.
267	        UpdateModelAnimation(character->model, animation, frame);
268	    }
269	
270	    // Uniform height: scale so every character stands ~1.8 units tall, feet
271	    // on the ground, rotated to the game's facing convention (0 → +Z).
272	    const BoundingBox bb = GetModelBoundingBox(character->model);
273	    const float modelHeight = bb.max.y - bb.min.y;
274	    const float s = modelHeight > 0.f ? 1.8f / modelHeight : 1.f;
275	    const Vector3 position{visual.position.x, -bb.min.y * s, visual.position.z};
276	    DrawModelEx(character->model, position, Vector3{0.f, 1.f, 0.f}, visual.facingDeg,
277	                Vector3{s, s, s}, WHITE);
278	
279	    // Non-neutral moods float as an emote above the head — the same six
280	    // procedural faces the legacy renderer painted on, now billboarded.
281	    // The dead don't emote.
282	    if (!visual.dead && visual.face != NpcFace::Neutral) {
283	        DrawBillboard(camera_, assets_.faceTexture(visual.face),
284	                      Vector3{visual.position.x, 2.45f, visual.position.z}, 0.55f,
285	                      WHITE);
286	    }
287	}
