289	void RaylibRenderer::drawViewmodel(int weaponKind, float attackFraction) {
290	    // Per-weapon visuals live in this table; adding a WeaponKind means
291	    // adding a row, never a new code branch. Sizes are camera-space meters.
292	    struct ViewSpec {
293	        Vector3 size;        // main body (fist / gun body)
294	        Color color;
295	        float thrust;        // + pushes forward on attack (punch), - recoils
296	        bool grip;           // draw a pistol-style grip under the body
297	    };
298	    static const ViewSpec kSpecs[] = {
299	        {{0.11f, 0.09f, 0.14f}, Color{224, 172, 138, 255}, 0.45f, false},  // Fist
300	        {{0.05f, 0.07f, 0.30f}, Color{55, 58, 66, 255}, -0.14f, true},     // Pistol
301	    };
302	    const int count = static_cast<int>(sizeof(kSpecs) / sizeof(kSpecs[0]));
303	    if (weaponKind < 0 || weaponKind >= count) return;
304	    const ViewSpec& spec = kSpecs[weaponKind];
305	
306	    // Camera basis for a lower-right anchored prop.
307	    const Vector3 fwd{camera_.target.x - camera_.position.x,
308	                      camera_.target.y - camera_.position.y,
309	                      camera_.target.z - camera_.position.z};
310	    const float flen = std::sqrt(fwd.x * fwd.x + fwd.y * fwd.y + fwd.z * fwd.z);
311	    if (flen < 1e-4f) return;
312	    const Vector3 f{fwd.x / flen, fwd.y / flen, fwd.z / flen};
313	    // Same right-vector convention as the game's strafe (flatRight in
314	    // main.cpp): cross(forward, up) = (-fz, 0, fx).
315	    const Vector3 r{-f.z, 0.f, f.x};
316	
317	    const float push = spec.thrust * attackFraction;
318	    const Vector3 base{
319	        camera_.position.x + f.x * (0.85f + push) + r.x * 0.32f,
320	        camera_.position.y - 0.28f + f.y * (0.85f + push),
321	        camera_.position.z + f.z * (0.85f + push) + r.z * 0.32f};
322	
323	    DrawCubeV(base, spec.size, spec.color);
324	    if (spec.grip) {
325	        DrawCubeV(Vector3{base.x - f.x * 0.10f, base.y - 0.07f, base.z - f.z * 0.10f},
326	                  Vector3{0.045f, 0.10f, 0.06f}, spec.color);
327	    }
328	}
329	
330	void RaylibRenderer::endFrame() {
331	    if (assets_.fogShader()) EndShaderMode();
332	    EndMode3D();
333	}
334	
335	bool RaylibRenderer::worldToScreen(const Vec3& world, Vector2& out) const {
336	    // Reject points behind the camera: GetWorldToScreen would mirror them.
337	    const Vector3 toPoint{world.x - camera_.position.x, world.y - camera_.position.y,
338	                          world.z - camera_.position.z};
339	    const Vector3 forward{camera_.target.x - camera_.position.x,
340	                          camera_.target.y - camera_.position.y,
341	                          camera_.target.z - camera_.position.z};
342	    if (toPoint.x * forward.x + toPoint.y * forward.y + toPoint.z * forward.z <= 0.f) {
343	        return false;
344	    }
345	    out = GetWorldToScreen({world.x, world.y, world.z}, camera_);
346	    return true;
347	}
